import { connectToDatabase, isDbConnected } from './mongodb';
import Vehicle from '@/models/Vehicle';
import ServiceRecord from '@/models/ServiceRecord';
import { mockVehicles, mockServices, getMockVehicles, getMockServices } from './mockStore';

// Get all vehicles
export async function getVehicles() {
  try {
    await connectToDatabase();
    if (isDbConnected()) {
      const docs = await Vehicle.find().sort({ createdAt: -1 }).lean();
      if (docs.length === 0) {
        // Auto-seed initial records
        await Vehicle.insertMany(mockVehicles.map(({ _id, ...rest }) => rest));
        return await Vehicle.find().sort({ createdAt: -1 }).lean();
      }
      return docs.map(d => ({ ...d, id: d._id.toString() }));
    }
  } catch (err) {
    console.warn('Fallback to memory for getVehicles:', err.message);
  }
  return getMockVehicles().map(v => ({ ...v, id: v._id || v.id }));
}

// Create new vehicle
export async function createVehicle(data) {
  const cleanData = {
    ...data,
    vehicleNo: data.vehicleNo.trim().toUpperCase(),
    rNo: data.rNo || `R-${String(Date.now()).slice(-3)}`
  };

  try {
    await connectToDatabase();
    if (isDbConnected()) {
      const doc = await Vehicle.create(cleanData);
      return { ...doc.toObject(), id: doc._id.toString() };
    }
  } catch (err) {
    console.warn('Fallback to memory for createVehicle:', err.message);
  }

  const list = getMockVehicles();
  const newObj = {
    _id: 'veh_' + Date.now(),
    id: 'veh_' + Date.now(),
    ...cleanData,
    createdAt: new Date().toISOString()
  };
  list.unshift(newObj);
  return newObj;
}

// Update vehicle
export async function updateVehicle(id, data) {
  if (data.vehicleNo) {
    data.vehicleNo = data.vehicleNo.trim().toUpperCase();
  }

  try {
    await connectToDatabase();
    if (isDbConnected()) {
      const doc = await Vehicle.findByIdAndUpdate(id, data, { new: true }).lean();
      if (doc) return { ...doc, id: doc._id.toString() };
    }
  } catch (err) {
    console.warn('Fallback to memory for updateVehicle:', err.message);
  }

  const list = getMockVehicles();
  const idx = list.findIndex(v => v._id === id || v.id === id || v.vehicleNo === id);
  if (idx !== -1) {
    list[idx] = { ...list[idx], ...data };
    return list[idx];
  }
  return null;
}

// Delete vehicle
export async function deleteVehicle(id) {
  try {
    await connectToDatabase();
    if (isDbConnected()) {
      await Vehicle.findByIdAndDelete(id);
      return true;
    }
  } catch (err) {
    console.warn('Fallback to memory for deleteVehicle:', err.message);
  }

  const list = getMockVehicles();
  const idx = list.findIndex(v => v._id === id || v.id === id || v.vehicleNo === id);
  if (idx !== -1) {
    list.splice(idx, 1);
    return true;
  }
  return false;
}

// Get service history for a specific vehicle number
export async function getServicesByVehicleNo(vehicleNo) {
  const vNo = vehicleNo ? vehicleNo.trim().toUpperCase() : '';

  try {
    await connectToDatabase();
    if (isDbConnected()) {
      const query = vNo ? { vehicleNo: vNo } : {};
      const docs = await ServiceRecord.find(query).sort({ serviceDate: -1, createdAt: -1 }).lean();
      if (docs.length === 0 && !vNo) {
        await ServiceRecord.insertMany(mockServices.map(({ _id, ...rest }) => rest));
        return await ServiceRecord.find().sort({ serviceDate: -1, createdAt: -1 }).lean();
      }
      return docs.map(d => ({ ...d, id: d._id.toString() }));
    }
  } catch (err) {
    console.warn('Fallback to memory for getServicesByVehicleNo:', err.message);
  }

  const list = getMockServices();
  const filtered = vNo ? list.filter(s => s.vehicleNo.toUpperCase() === vNo) : list;
  return filtered.sort((a, b) => new Date(b.serviceDate) - new Date(a.serviceDate));
}

// Create new service record
export async function createServiceRecord(data) {
  const cleanData = {
    ...data,
    vehicleNo: data.vehicleNo.trim().toUpperCase(),
    serviceNo: data.serviceNo || `SRV-${new Date().getFullYear()}-${Math.floor(100 + Math.random() * 900)}`,
    odometer: Number(data.odometer) || 0,
    laborCharges: Number(data.laborCharges) || 0,
    discount: Number(data.discount) || 0,
    totalAmount: Number(data.totalAmount) || 0,
    nextServiceMileage: Number(data.nextServiceMileage) || (Number(data.odometer) ? Number(data.odometer) + 5000 : 0)
  };

  try {
    await connectToDatabase();
    if (isDbConnected()) {
      const doc = await ServiceRecord.create(cleanData);
      return { ...doc.toObject(), id: doc._id.toString() };
    }
  } catch (err) {
    console.warn('Fallback to memory for createServiceRecord:', err.message);
  }

  const list = getMockServices();
  const newObj = {
    _id: 'srv_' + Date.now(),
    id: 'srv_' + Date.now(),
    ...cleanData,
    createdAt: new Date().toISOString()
  };
  list.unshift(newObj);
  return newObj;
}

