import mongoose from 'mongoose';

const InvoiceItemSchema = new mongoose.Schema({
  no: { type: Number, required: true },
  code: { type: String, required: true },
  description: { type: String, required: true },
  qty: { type: Number, default: 1 },
  rate: { type: Number, default: 0 },
  dis: { type: Number, default: 0 },
  amount: { type: Number, default: 0 },
  itemType: { type: String, enum: ['item', 'job'], default: 'item' }
}, { _id: false });

const ServiceRecordSchema = new mongoose.Schema(
  {
    invoiceNo: { type: String, required: true, trim: true, index: true },
    vehicleNo: { type: String, required: true, uppercase: true, trim: true, index: true },
    customerType: { type: String, default: 'Regular' },
    csName: { type: String, required: true, trim: true },
    csAddress: { type: String, default: '' },
    telephone: { type: String, default: '' },
    city: { type: String, default: '' },
    vModel: { type: String, default: '' },
    engineNo: { type: String, default: '' },
    chassisNo: { type: String, default: '' },
    jobDetails: { type: String, default: '' },
    meterReading: { type: Number, required: true, default: 0 }, // M.Reading
    jobDone: { type: String, default: 'Pending' },
    serviceDate: { type: String, required: true }, // Date (e.g., 2026-10-28)
    serviceTime: { type: String, default: '' },

    // Financial breakdown matching Job Invoicing screen
    billingType: { type: String, enum: ['Normal', 'VAT Bill'], default: 'Normal' },
    partsTotal: { type: Number, default: 0 },
    jobTotal: { type: Number, default: 0 },
    totalAmount: { type: Number, default: 0 },
    discountPercent: { type: Number, default: 0 },
    totalDis: { type: Number, default: 0 },
    grandTotal: { type: Number, default: 0 },
    vat: { type: Number, default: 0 },
    nbt: { type: Number, default: 0 },
    billTotal: { type: Number, default: 0 },

    // Items and Jobs line items
    items: [InvoiceItemSchema],

    // Next service reminders
    nextServiceDate: { type: String, default: '' },
    nextServiceMeter: { type: Number, default: 0 },
    paymentType: { type: String, enum: ['CASH', 'PAYMENTS'], default: 'CASH' },
    status: { type: String, default: 'Completed', enum: ['Open', 'Completed', 'Invoiced'] }
  },
  {
    timestamps: true
  }
);

export default mongoose.models.ServiceRecord || mongoose.model('ServiceRecord', ServiceRecordSchema);
